/// <summary>Imports orders from a batch of delimited rows.</summary>
public sealed class OrderImporter
{
    private readonly OrderRepository _repository;

    public OrderImporter(OrderRepository repository) => _repository = repository;

    public IReadOnlyList<Order> ImportBatch(IEnumerable<string> rows)
    {
        var imported = new List<Order>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var row in rows)
        {
            var order = ParseOrder(row, seen);
            if (order is null)
                continue;

            _repository.Add(order);
            imported.Add(order);
        }

        return imported;
    }

    private static Order? ParseOrder(string row, HashSet<string> seen)
    {
        if (string.IsNullOrWhiteSpace(row))
            return null;

        var parts = row.Split(',');
        if (parts.Length < 4)
            return null;

        var recordType = parts[0].Trim();
        var reference = parts[1].Trim();
        if (reference.Length == 0 || !seen.Add(reference))
            return null;

        var order = CreateOrder(recordType, reference);
        if (order is null)
            return null;

        AddLines(order, parts);
        return order.Lines.Count == 0 ? null : order;
    }

    private static Order? CreateOrder(string recordType, string reference) => recordType switch
    {
        "H" or "ORDER" => new Order
        {
            Reference = reference,
            Channel = OrderChannel.Web
        },
        "M" => new Order
        {
            Reference = reference,
            Channel = OrderChannel.Marketplace
        },
        _ => null
    };

    private static void AddLines(Order order, string[] parts)
    {
        for (var i = 2; i + 1 < parts.Length; i += 2)
        {
            var sku = parts[i].Trim();
            if (sku.Length == 0)
                continue;

            if (!int.TryParse(parts[i + 1], out var quantity) || quantity <= 0)
                continue;

            order.Lines.Add(new OrderLine
            {
                Sku = sku,
                Quantity = quantity,
                UnitPrice = CalculateUnitPrice(sku, quantity)
            });
        }
    }

    private static decimal CalculateUnitPrice(string sku, int quantity)
    {
        if (sku.StartsWith("PRM", StringComparison.Ordinal) && quantity > 10)
            return 9.99m;

        return sku.StartsWith("STD", StringComparison.Ordinal) ? 4.99m : 0m;
    }
}
